'use server';

import { adminDb } from '@/firebase/admin';
import { revalidatePath } from 'next/cache';

interface ContactInfo {
  avatarUrl?: string;
  name?: string;
  title?: string;
  email?: string;
  whatsApp?: string;
  behanceUrl?: string;
  linkedinUrl?: string;
  fiverrUrl?: string;
  instagramUrl?: string;
  facebookUrl?: string;
  twitterUrl?: string;
}

/**
 * Updates the contact information in Firestore.
 * @param contactData The new contact information.
 */
export async function updateContactInfo(contactData: ContactInfo) {
  try {
    const contactDocRef = adminDb.collection('contact').doc('details');
    await contactDocRef.set(contactData, { merge: true });
    revalidatePath('/admin');
    revalidatePath('/contact');
  } catch (error) {
    console.error('Error updating contact info:', error);
    throw new Error('Could not update contact information.');
  }
}
