'use server';

import { adminDb } from '@/firebase/admin';
import { revalidatePath } from 'next/cache';
import type { PortfolioItem } from '@/features/portfolio/data/portfolio-data';

// Helper function to get the projects collection
const projectsCollection = adminDb.collection('projects');

/**
 * Adds a new project to the Firestore 'projects' collection.
 * @param projectData The data for the new project.
 */
export async function addProject(projectData: Omit<PortfolioItem, 'id'>) {
  try {
    const docRef = await projectsCollection.add(projectData);
    revalidatePath('/admin');
    revalidatePath('/work');
    return { id: docRef.id, ...projectData };
  } catch (error) {
    console.error('Error adding project:', error);
    throw new Error('Could not add project.');
  }
}

/**
 * Updates an existing project in the Firestore 'projects' collection.
 * @param projectId The ID of the project to update.
 * @param updates The fields to update.
 */
export async function updateProject(projectId: string, updates: Partial<PortfolioItem>) {
  try {
    await projectsCollection.doc(projectId).set(updates, { merge: true });
    revalidatePath('/admin');
    revalidatePath('/work');
  } catch (error) {
    console.error('Error updating project:', error);
    throw new Error('Could not update project.');
  }
}

/**
 * Deletes a project from the Firestore 'projects' collection.
 * @param projectId The ID of the project to delete.
 */
export async function deleteProject(projectId: string) {
  try {
    await projectsCollection.doc(projectId).delete();
    revalidatePath('/admin');
    revalidatePath('/work');
  } catch (error) {
    console.error('Error deleting project:', error);
    throw new Error('Could not delete project.');
  }
}

/**
 * Reorders projects based on an array of their IDs.
 * @param orderedIds An array of project IDs in the desired order.
 */
export async function reorderProjects(orderedIds: string[]) {
    try {
        const batch = adminDb.batch();
        orderedIds.forEach((id, index) => {
            const docRef = projectsCollection.doc(id);
            batch.update(docRef, { order: index });
        });
        await batch.commit();
        revalidatePath('/admin');
        revalidatePath('/work');
    } catch (error) {
        console.error('Error reordering projects:', error);
        throw new Error('Could not reorder projects.');
    }
}
