'use server';

import { adminDb } from '@/firebase/admin';
import { revalidatePath } from 'next/cache';

interface MediaAssetData {
    public_id: string;
    url: string;
    resource_type: 'image' | 'video' | 'raw';
    created_at: string;
    filename: string;
}

/**
 * Adds a new media asset's metadata to Firestore.
 * @param assetData The metadata of the uploaded asset.
 */
export async function addMediaAsset(assetData: MediaAssetData) {
  try {
    await adminDb.collection('media').add(assetData);
    revalidatePath('/admin');
  } catch (error) {
    console.error('Error adding media asset:', error);
    throw new Error('Could not save media asset to the library.');
  }
}

/**
 * Deletes a media asset's metadata from Firestore.
 * @param mediaId The ID of the media document to delete.
 */
export async function deleteMediaAsset(mediaId: string) {
  try {
    await adminDb.collection('media').doc(mediaId).delete();
    revalidatePath('/admin');
  } catch (error) {
    console.error('Error deleting media asset:', error);
    throw new Error('Could not delete media asset from the library.');
  }
}
