
'use server';

import { v2 as cloudinary } from 'cloudinary';

const isCloudinaryConfigured = () => {
    return !!process.env.CLOUDINARY_CLOUD_NAME && 
           !!process.env.CLOUDINARY_API_KEY && 
           !!process.env.CLOUDINARY_API_SECRET;
}

const configureCloudinary = () => {
    cloudinary.config({
        cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
        api_key: process.env.CLOUDINARY_API_KEY,
        api_secret: process.env.CLOUDINARY_API_SECRET,
    });
};

/**
 * Deletes an asset from Cloudinary using its public ID.
 * @param publicId The public ID of the asset to delete.
 * @param resourceType The type of the resource ('image', 'video', 'raw').
 */
export async function deleteCloudinaryAsset(publicId: string, resourceType: 'image' | 'video' | 'raw' = 'image') {
    if (!isCloudinaryConfigured()) {
        throw new Error('Server is not configured for Cloudinary operations.');
    }

    configureCloudinary();
    
    try {
        const result = await cloudinary.uploader.destroy(publicId, {
            resource_type: resourceType,
        });

        if (result.result !== 'ok' && result.result !== 'not found') {
            throw new Error(result.result || 'Failed to delete asset from Cloudinary.');
        }
        
        return { success: true, message: 'Asset deleted successfully from Cloudinary.' };
    } catch (error: any) {
        console.error('Cloudinary deletion error:', error);
        throw new Error(error.message || 'An unexpected error occurred during Cloudinary deletion.');
    }
}
